// Mix local narration, or neural speech previously generated by synthesize-neural-walkthrough.py.
import {execFileSync,spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync,mkdirSync,existsSync} from 'node:fs';
import {resolve} from 'node:path';

const root=resolve('artifacts/walkthrough-2026-09-14');
const neural=process.argv.includes('--neural');
const voice=neural?'en-IN-NeerjaExpressiveNeural':'Rishi';
const edition=neural?'sasa-walkthrough-neural-indian-english':'sasa-walkthrough-indian-english';
const out=resolve(root,neural?'narration-neural':'narration');
mkdirSync(out,{recursive:true});
const {cues}=JSON.parse(readFileSync(resolve(root,'timeline.json'),'utf8'));
const probe=path=>JSON.parse(execFileSync('ffprobe',['-v','error','-show_entries','format=duration','-of','json',path],{encoding:'utf8'})).format.duration*1;
const entries=[];
for(const [i,cue] of cues.entries()) {
  // Spell the initialism for speech; the visible caption keeps normal typography.
  const text=cue.text.replace(/ULB’s/g,'U L B’s').replace(/ULBs/g,'U L Bs').replace(/ULB/g,'U L B').replace(/May–August/g,'May to August').replace(/12 August 2026/g,'the twelfth of August, twenty twenty six').replace(/panchayat-day/g,'panchayat day');
  const stem=resolve(out,String(i+1).padStart(2,'0'));
  writeFileSync(stem+'.txt',text);
  if(!neural && (!process.argv.includes('--reuse-audio')||!existsSync(stem+'.aiff'))) execFileSync('say',['-v','Rishi','-r','160','-f',stem+'.txt','-o',stem+'.aiff']);
  const source=stem+(neural?'.wav':'.aiff');
  const duration=probe(source);
  const available=cue.end-cue.start-.45;
  const tempo=Math.max(1,duration/available);
  entries.push({...cue,spokenText:text,source,duration,available,tempo,start:cue.start+.15});
  console.log(`${i+1}: ${duration.toFixed(2)}s / ${available.toFixed(2)}s; tempo ${tempo.toFixed(3)}`);
}
writeFileSync(resolve(out,'speech-plan.json'),JSON.stringify({voice,locale:'en-IN',engine:neural?'Microsoft Edge neural speech':'macOS speech synthesis',entries},null,2));
if(process.argv.includes('--synthesize-only'))process.exit(0);
if(entries.some(e=>e.tempo>1.2))throw new Error('Narration would be rushed: revise the rate or scene timings before mixing.');
const video=resolve(root,'sasa-walkthrough.mp4');
const total=probe(video);
const filters=[];
const inputs=[];
entries.forEach((e,i)=>{
  inputs.push('-i',e.source);
  filters.push(`[${i}:a]aresample=48000,atempo=${e.tempo.toFixed(6)},afade=t=in:d=0.018,afade=t=out:st=${(e.duration/e.tempo-.04).toFixed(6)}:d=0.04,asetpts=N/SR/TB,adelay=${Math.round(e.start*1000)}:all=1[a${i}]`);
});
filters.push(`${entries.map((_,i)=>`[a${i}]`).join('')}amix=inputs=${entries.length}:duration=longest:normalize=0,asetpts=N/SR/TB,apad=whole_dur=${total},atrim=end_sample=${Math.round(total*48000)}[mix]`);
writeFileSync(resolve(out,'mix.ffscript'),filters.join(';\n'));
const raw=resolve(out,'narration-mix.wav');
execFileSync('ffmpeg',['-v','error','-y',...inputs,'-filter_complex_script',resolve(out,'mix.ffscript'),'-map','[mix]','-ar','48000','-ac','1','-t',String(total),'-fs','64000000','-c:a','pcm_s24le',raw],{timeout:60000});
// Two-pass broadcast-style loudness normalization, with ample true-peak headroom.
const result=spawnSync('ffmpeg',['-hide_banner','-i',raw,'-af','loudnorm=I=-16:TP=-1.5:LRA=9:print_format=json','-f','null','-'],{encoding:'utf8'});
if(result.status!==0)throw new Error(result.stderr);
const measure=JSON.parse(result.stderr.match(/\{[\s\S]*\}/)[0]);
const normalized=resolve(root,edition+'.wav');
const norm=`loudnorm=I=-16:TP=-1.5:LRA=9:measured_I=${measure.input_i}:measured_TP=${measure.input_tp}:measured_LRA=${measure.input_lra}:measured_thresh=${measure.input_thresh}:offset=${measure.target_offset}:linear=true`;
execFileSync('ffmpeg',['-v','error','-y','-i',raw,'-af',norm,'-ar','48000','-c:a','pcm_s16le',normalized]);
const final=resolve(root,edition+'.mp4');
execFileSync('ffmpeg',['-v','error','-y','-i',video,'-i',normalized,'-map','0:v:0','-map','1:a:0','-map','0:s?','-c:v','copy','-c:a','aac','-b:a','192k','-c:s','copy','-disposition:s:0','0','-metadata:s:a:0','language=eng','-metadata',`comment=Indian English synthetic narration using ${voice}.`,'-movflags','+faststart',final]);
writeFileSync(resolve(out,'audio-qa.json'),JSON.stringify({voice,locale:'en-IN',synthetic:true,scenes:entries.length,totalDuration:total,maxTempo:Math.max(...entries.map(e=>e.tempo)),loudnessMeasurement:measure,final},null,2));
console.log(final);
